// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health", wrapper.HealthCheck)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/hello", wrapper.HelloWorld)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/auth/register", wrapper.Register)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/auth/login", wrapper.Login)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/auth/refresh", wrapper.RefreshToken)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/auth/logout", wrapper.Logout)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/users/me", wrapper.DeleteCurrentUser)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/users/me", wrapper.GetCurrentUser)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/users/me", wrapper.UpdateCurrentUser)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/users/me/password", wrapper.ChangePassword)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/habits", wrapper.ListHabits)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/habits", wrapper.CreateHabit)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/habits/{habitId}", wrapper.DeleteHabit)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/habits/{habitId}", wrapper.UpdateHabit)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/completions", wrapper.ListCompletionsInRange)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/habits/{habitId}/completions", wrapper.ListCompletions)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/habits/{habitId}/completions", wrapper.CreateCompletion)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/habits/{habitId}/stats", wrapper.GetHabitStats)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/habits/{habitId}/completions/{date}", wrapper.DeleteCompletion)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/habits/{habitId}/completions/{date}", wrapper.UpdateCompletionNote)

	return m
}

